let overlayLayoutEditing=false,overlaySaveTimer=null;
const state={presets:[],active:null,selected:null,events:[],actions:[],connected:false,connectionState:'disconnected',activeMode:'tiktok',activeUsername:'',selectedMode:null,connectionInitialized:false,logs:[],logsBusy:false,ws:null,games:[],gifts:[],displayGifts:[],gameFilter:'all',gameQuery:'',giftSort:'popular',giftPage:0,giftPageSize:60,ruleGiftQuery:'',ruleGiftChoice:null,ruleSoundChoice:null,artRecoveryAttempted:false,downloadAvailable:false,downloadMessage:'',lastUpdateCheckId:0,manualUpdatePending:false,manualUpdateCheckBefore:0,liveConfig:{tts_enabled:false,tts_voice:'pl-PL',sound_alerts:false,sound_volume:.55,sound_url:'',overlay_template:'grid',overlay_opacity:.72,overlay_density:'balanced',overlay_canvas:'landscape',overlay_positions_landscape:{},overlay_positions_portrait:{}},lastSpeechAt:0,lastSoundAt:0,audioContext:null,earningsSettings:{usd_per_diamond:.005,usd_to_pln:4},totalDiamonds:0,totalGifts:0,donors:[]};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cleanEmoji=s=>String(s??'').replace(/\p{Extended_Pictographic}/gu,'').replace(/\s{2,}/g,' ').trim();
const triggerSymbols={gift:'◇',like:'♡',follow:'＋',comment:'⌕',share:'↗',join:'○',subscribe:'★'};
const giftBoxSvg='<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M8 21h32v19H8zM5 15h38v9H5zM21 15h6v25h-6z" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/><path d="M24 15c-10 0-12-9-6-9 4 0 6 9 6 9Zm0 0c10 0 12-9 6-9-4 0-6 9-6 9Z" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/></svg>';
const normalizedGiftName=name=>({doughnut:'donut',rosa:'rose'}[String(name||'').trim().toLowerCase()]||String(name||'').trim().toLowerCase());
function findGift(name,id){return state.gifts.find(g=>(id!=null&&String(g.id)===String(id))||normalizedGiftName(g.name)===normalizedGiftName(name)||normalizedGiftName(g.label_pl)===normalizedGiftName(name))}
function trustedGiftUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&['tiktokcdn.com','tiktokcdn-us.com','tiktokcdn-eu.com'].some(host=>u.hostname===host||u.hostname.endsWith(`.${host}`))?`/api/gifts/image?url=${encodeURIComponent(u.href)}`:''}catch{return ''}}
function giftArt(name,id,classes='gift-artwork',imageUrl=''){const gift=findGift(name,id),src=trustedGiftUrl(imageUrl)||gift?.image_url;return src?`<img class="${classes}" data-tiktok-art src="${esc(src)}" alt="${esc(gift?.label_pl||gift?.name||name||'Prezent TikTok')}" loading="lazy">`:`<span class="${classes} gift-art-placeholder" aria-hidden="true">${giftBoxSvg}</span>`}
function eventIconMarkup(event){return event?.type==='gift'?giftArt(event.gift_name,event.gift_id,'feed-gift-art',event.gift_image_url):`<span class="feed-icon">${triggerSymbols[event?.type]||'·'}</span>`}
function bindGiftArt(root=document){root.querySelectorAll('img[data-tiktok-art]').forEach(img=>img.onerror=()=>{if(!state.artRecoveryAttempted){state.artRecoveryAttempted=true;post('/api/gifts/refresh').then(()=>fillGifts()).catch(()=>{})}const fallback=document.createElement('span');fallback.className=`${img.className} gift-art-placeholder`;fallback.setAttribute('aria-hidden','true');fallback.title='Grafika chwilowo niedostępna — spróbuj odświeżyć katalog';fallback.innerHTML=giftBoxSvg;const card=img.closest('.gift-library-card'),source=card?.querySelector('.gift-source');if(source){source.textContent='GRAFIKA NIEDOSTĘPNA';source.classList.remove('real')}img.replaceWith(fallback)})}
const coinText=(value,estimated=false)=>{const n=Number(value||0);if(!Number.isFinite(n)||n<=0)return 'cena nieudostępniona';const m10=n%10,m100=n%100,unit=n===1?'moneta':m10>=2&&m10<=4&&(m100<12||m100>14)?'monety':'monet';return `${estimated?'≈':''}${n.toLocaleString('pl-PL')} ${unit}`};
const typePL={gift:'Prezent',like:'Polubienie',follow:'Obserwacja',comment:'Komentarz',share:'Udostępnienie',join:'Dołączenie',subscribe:'Subskrypcja',system:'System'};
const actionStatusPL={pending:'OCZEKUJE',succeeded:'WYKONANO',failed:'BŁĄD',skipped:'POMINIĘTO',sent:'WYSŁANO'};
const actionPL={parkour_push:'Delikatny push',parkour_level_forward:'Następny poziom',parkour_level_back:'Poprzedni poziom',parkour_jail:'Więzienie',parkour_reset:'Reset za 60 s',parkour_antireset:'Anty-reset',parkour_speed:'Sprint · 8 s',parkour_slow:'Spowolnienie · 7 s',parkour_blind:'Ciemność · 4 s',parkour_jump:'Wysoki skok · 4 s',parkour_shield:'Tarcza · 6 s',parkour_cleanse:'Usuń negatywne efekty',dropper_push:'Dropper: push',dropper_level_forward:'Dropper: wyższy poziom',dropper_level_back:'Dropper: niższy poziom',dropper_reset:'Dropper: powrót na start',dropper_speed:'Dropper: sprint · 8 s',dropper_slow:'Dropper: spowolnienie · 7 s',dropper_blind:'Dropper: ciemność · 4 s',dropper_jump:'Dropper: wysoki skok',dropper_shield:'Dropper: tarcza · 6 s',dropper_cleanse:'Dropper: oczyszczenie',spawn_zombie:'Przywołaj zombie',spawn_enemy:'Przywołaj przeciwnika',spawn_boss:'Przywołaj bossa',boss_raid:'Fala bossów',heal:'Ulecz gracza',drop_diamond:'Upuść diament',drop_item:'Upuść przedmiot',give_item:'Daj przedmiot',move_left:'Ruch w lewo',move_right:'Ruch w prawo',jump:'Skok',shield:'Tarcza',speed_boost:'Przyspieszenie',teleport:'Teleport',spawn_wall:'Stwórz przeszkodę',change_weather:'Zmień pogodę',change_time:'Zmień porę dnia',screen_shake:'Trzęsienie ekranu',confetti:'Konfetti',vote:'Głosowanie',custom:'Akcja własna'};
const giftPL={'Rose':'Róża','Doughnut':'Donut','Donut':'Donut','Ice Cream':'Lody','Finger Heart':'Serduszko z palców','Sunglasses':'Okulary','Money Gun':'Pistolet na pieniądze','Dragon':'Smok','Lion':'Lew','TikTok Universe':'Wszechświat TikToka'};
const toast=msg=>{const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)};
async function api(path,opt={}){const r=await fetch(path,{cache:'no-store',headers:{'Content-Type':'application/json'},...opt});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.detail||'Nie udało się wykonać żądania');return data}
const post=(path,body={})=>api(path,{method:'POST',body:JSON.stringify(body)});
function closeMobileNav(){const wasOpen=document.body.classList.contains('sidebar-open');document.body.classList.remove('sidebar-open');const menu=$('#menu-toggle');menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Otwórz menu');if(wasOpen&&window.innerWidth<=800)menu?.focus()}
function setView(name,pushHistory=true){if(!$(`#view-${name}`))name='overview';$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-link').forEach(a=>{const active=a.dataset.view===name;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#crumb-current').textContent=({overview:'Pulpit',presets:'Reguły gry',events:'Aktywność',gifts:'Biblioteka giftów',sounds:'Dźwięki i alerty',overlay:'Nakładka OBS',bridge:'Konfiguracja Minecraft'})[name]||name;if(pushHistory&&location.hash!==`#${name}`)history.pushState({view:name},'',`#${name}`);closeMobileNav();if(name!=='events'&&$('#event-search')?.value){$('#event-search').value='';renderFeed()}if(name==='overlay')updateOverlayPreview();if(name==='gifts')loadGiftLibrary();window.scrollTo({top:0,behavior:'smooth'})}
const plnText=value=>`${Number(value||0).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2})} zł`;
function giftPayout(diamonds,count=1){return Math.max(0,Number(diamonds)||0)*Math.max(1,Number(count)||1)*state.earningsSettings.usd_per_diamond*state.earningsSettings.usd_to_pln}
function eventDescriptionCore(e){if(e.type==='gift'){const gift=findGift(e.gift_name,e.gift_id),diamonds=Number(e.earning_diamonds??e.diamonds)||0,repeat=Math.max(1,Number(e.repeat_count)||1),eventCoins=!e.gift_coins_estimated?Number(e.gift_coins)||0:0,catalogCoins=gift&&!gift.coins_estimated?Number(gift.coins)||0:0,coinValue=eventCoins||catalogCoins,price=coinValue?`${coinText(coinValue*repeat)} łącznie od widza`:'cena niepodana przez TikToka',payout=e.repeat_end===false?'seria w toku':diamonds?`≈ ${plnText(giftPayout(diamonds,repeat))}`:'diamenty twórcy po synchronizacji LIVE';return `${gift?.label_pl||giftPL[e.gift_name]||e.gift_name||'Prezent'}${repeat>1?` ×${repeat}`:''} · ${price} · ${payout}`};if(e.type==='comment')return `„${e.comment||''}”`;if(e.type==='like')return `Polubienia ×${e.like_count||1}`;return ({follow:'Nowa obserwacja',join:'Dołączył do transmisji',share:'Udostępnił transmisję',subscribe:'Nowa subskrypcja'})[e.type]||typePL[e.type]||e.type}
function eventDescription(e){const text=eventDescriptionCore(e),source=e.source==='browser'?'Browser lokalny':e.source==='tiktok'?'TikTokLive':e.source;return source?`${text} · ${source}`:text}
function timeLabel(ts){const d=new Date((ts||Date.now()/1000)*1000);return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function renderFeed(){let combined=[...state.events.map(e=>({kind:'event',data:e})),...state.actions.map(a=>({kind:'action',data:a}))].sort((a,b)=>(b.data.ts||0)-(a.data.ts||0)).slice(0,200);const query=$('#event-search')?.value.trim().toLocaleLowerCase('pl-PL')||'';if(query)combined=combined.filter(x=>{const d=x.data,ev=x.kind==='action'?d.triggered_by:d;return `${eventDescription(ev||{})} ${ev?.nickname||''} ${ev?.user||''} ${d.rule_name||''} ${d.action||''}`.toLocaleLowerCase('pl-PL').includes(query)});const markup=combined.map(x=>{const d=x.data;const ev=x.kind==='action'?d.triggered_by:d;const isAction=x.kind==='action';let desc=isAction?`${actionStatusPL[d.execution_status]||'AKCJA'}: ${d.rule_name||actionPL[d.action]||d.action}${d.execution_message?` · ${d.execution_message}`:''}`:eventDescription(d);return `<div class="feed-row"><div class="feed-event">${isAction?'<span class="feed-icon"><img src="/static/giftstream.svg" alt=""></span>':eventIconMarkup(ev)}<span>${isAction?`<span class="action-badge action-${esc(d.execution_status||'pending')}">${actionStatusPL[d.execution_status]||'AKCJA'}</span>`:esc(typePL[ev?.type]||'Zdarzenie')}</span></div><span class="feed-user">${esc(ev?.nickname||ev?.user||'—')}</span><span class="feed-detail">${esc(desc)}</span><span class="feed-time">${timeLabel(d.ts)}</span></div>`}).join('');$('#activity-list').innerHTML=combined.length?combined.slice(0,5).map(x=>{let d=x.data,ev=x.kind==='action'?d.triggered_by:d;return `<div class="feed-row"><div class="feed-event">${x.kind==='action'?'<span class="feed-icon"><img src="/static/giftstream.svg" alt=""></span>':eventIconMarkup(ev)}<span>${esc(typePL[ev?.type]||'Zdarzenie')}</span></div><span class="feed-user">${esc(ev?.nickname||ev?.user||'—')}</span><span class="feed-detail">${esc(x.kind==='action'?`${actionStatusPL[d.execution_status]||'AKCJA'} · ${d.execution_message||d.rule_name||actionPL[d.action]||d.action}`:eventDescription(d))}</span><span class="feed-time">${timeLabel(d.ts)}</span></div>`}).join(''):`<div class="empty-state"><span class="empty-symbol">↯</span><strong>${query?'Brak pasujących zdarzeń':'Czekam na pierwsze zdarzenie'}</strong><small>${query?'Zmień frazę wyszukiwania.':'Połącz TikTok LIVE, aby zobaczyć zdarzenia.'}</small></div>`;$('#all-activity').innerHTML=markup||`<div class="empty-state"><span class="empty-symbol">↯</span><strong>${query?'Brak pasujących zdarzeń':'Brak zdarzeń'}</strong><small>${query?'Zmień frazę wyszukiwania.':'Połącz TikTok LIVE, aby zobaczyć zdarzenia.'}</small></div>`;bindGiftArt($('#activity-list'));bindGiftArt($('#all-activity'))}
function renderDonors(donors=[]){const max=Math.max(1,...donors.map(d=>Number(d.diamonds)||0));const rows=donors.map((d,i)=>`<div class="donor-row"><span class="donor-rank">${String(i+1).padStart(2,'0')}</span><span class="donor-avatar">${esc((d.user||'?').slice(0,1).toUpperCase())}</span><span class="donor-info"><span class="donor-name">@${esc(d.user)}</span><i style="width:${Math.max(5,Math.round((Number(d.diamonds)||0)*100/max))}%"></i></span><span class="donor-count" title="Szacunek na podstawie diamentów i skonfigurowanych stawek">${Number(d.diamonds).toLocaleString('pl-PL')} diamentów · ≈ ${plnText(giftPayout(d.diamonds))}</span></div>`).join('');$('#donor-list').innerHTML=rows||'<div class="empty-note">Jeszcze nie ma prezentów. Czas na chaos!</div>'}
function renderEarnings(){const total=giftPayout(state.totalDiamonds);$('#earnings-total').textContent=plnText(total);$('#earnings-diamonds').textContent=`${Number(state.totalDiamonds).toLocaleString('pl-PL')} diamentów`;$('#earnings-gifts').textContent=`${Number(state.totalGifts).toLocaleString('pl-PL')} giftów`}
function renderEarningsSettings(){const s=state.earningsSettings;$('#rate-diamond').value=s.usd_per_diamond;$('#rate-usd-pln').textContent=Number(s.usd_to_pln).toLocaleString('pl-PL',{minimumFractionDigits:4,maximumFractionDigits:4});$('#earnings-rate-status').textContent=s.usd_to_pln_updated?`${s.rate_source} · ${s.usd_to_pln_updated}`:s.rate_source;renderEarnings();renderFeed();renderDonors(state.donors)}
async function loadEarningsSettings(){try{state.earningsSettings=await api('/api/earnings/settings');renderEarningsSettings()}catch{}}
async function saveEarningsSettings(event){event.preventDefault();const status=$('#earnings-rate-status');try{state.earningsSettings=await api('/api/earnings/settings',{method:'PUT',body:JSON.stringify({usd_per_diamond:Number($('#rate-diamond').value)})});renderEarningsSettings();if(state.displayGifts.length)renderGiftLibrary();toast('Zapisano założenie wartości diamentu')}catch(e){status.textContent=e.message;toast(e.message)}}
async function refreshNbpRate(){const button=$('#refresh-nbp');button.disabled=true;try{const result=await post('/api/earnings/refresh-rate');state.earningsSettings=result.settings;renderEarningsSettings();toast(result.ok?'Zaktualizowano kurs NBP':result.message)}catch(e){toast(e.message)}finally{button.disabled=false}}
function renderActive(){const p=state.active;if(!p)return;$('#active-preset-name').textContent=p.name;const rules=p.rules||[];$('#active-rule-total').textContent=rules.filter(r=>r.enabled).length;$('#nav-rule-count').textContent=rules.filter(r=>r.enabled).length;$('#rule-preview').innerHTML=rules.filter(r=>r.enabled).slice(0,4).map(r=>`<div class="rule-preview-row"><span>${esc(giftPL[r.trigger.gift_name]||r.trigger.keyword||typePL[r.trigger.type]||r.trigger.type)}</span><span class="mini-arrow">→</span><b>${esc(actionPL[r.action.type]||r.action.type.replaceAll('_',' '))}</b></div>`).join('')||'<div class="empty-note">Ten preset nie ma jeszcze reguł.</div>';}
function syncModeToPreset(id){$('#parkour-game-mode').value=id==='minecraft-dropper'?'dropper':'parkour';updateMinecraftModeUI()}
function renderPresets(){const list=$('#preset-list');list.innerHTML=state.presets.map(p=>`<button class="preset-item ${state.selected?.id===p.id?'selected':''}" data-preset="${esc(p.id)}"><span class="preset-glyph">⌘</span><span class="preset-item-info"><b>${esc(p.name)}</b><small>${p.rules.filter(r=>r.enabled).length} aktywnych reguł</small></span>${p.id===state.active?.id?'<span class="active-tag">LIVE</span>':''}</button>`).join('');$$('.preset-item').forEach(b=>b.onclick=()=>selectPreset(b.dataset.preset));renderRules()}
function renderRules(){const p=state.selected;const box=$('#rules-list');$('#add-rule').disabled=!p;if(!p){box.innerHTML='<div class="empty-state">Wybierz preset, aby edytować jego reguły.</div>';$('#editor-title').textContent='Reguły presetu';$('#editor-sub').textContent='Wybierz preset, aby zobaczyć reguły';return}refreshRuleActionOptions();$('#editor-title').textContent=p.name;$('#editor-sub').textContent=`${p.rules.length} reguł · ${p.description||'Ustaw prezenty uruchamiające akcje'}`;box.innerHTML=p.rules.length?p.rules.map(r=>`<div class="rule-card ${r.enabled?'':'disabled'}"><span class="rule-icon">${r.trigger.type==='gift'?giftArt(r.trigger.gift_name,r.trigger.gift_id,'rule-gift-art'):`<span class="rule-icon-symbol">${triggerSymbols[r.trigger.type]||'·'}</span>`}</span><div><div class="rule-name">${esc(r.name||`${r.trigger.gift_name||r.trigger.type} → ${r.action.type}`)}</div><div class="rule-trigger-label">${esc(giftPL[r.trigger.gift_name]||r.trigger.keyword||typePL[r.trigger.type]||r.trigger.type)}${r.trigger.like_threshold?` · ${r.trigger.like_threshold}`:''}${r.trigger.min_coins!=null?` · ${Number(r.trigger.min_coins)}+ monet${r.trigger.max_coins!=null?` (do ${Number(r.trigger.max_coins)})`:''}`:''} ${r.interrupt?'· PRIORYTET':''}${r.sound?' · ♫ DŹWIĘK':''}</div></div><div class="rule-action-label"><span>→</span>${esc(actionPL[r.action.type]||r.action.type.replaceAll('_',' '))}</div><div class="rule-card-actions"><button class="tiny-action" data-toggle="${esc(r.id)}">${r.enabled?'Aktywna':'Wyłączona'}</button><button class="tiny-action" data-edit="${esc(r.id)}">Edytuj</button></div></div>`).join(''):'<div class="empty-state">Ten preset nie ma jeszcze reguł. Dodaj pierwszy prezent.</div>';bindGiftArt(box);$$('[data-toggle]').forEach(b=>b.onclick=()=>{const r=p.rules.find(x=>x.id===b.dataset.toggle);r.enabled=!r.enabled;saveSelected()});$$('[data-edit]').forEach(b=>b.onclick=()=>openRule(p.rules.find(x=>x.id===b.dataset.edit)))}
async function loadPresets(){try{state.presets=await api('/api/presets');const active=(await api('/api/status')).preset;state.active=state.presets.find(p=>p.id===active?.id)||state.presets[0]||null;state.selected=state.selected?state.presets.find(p=>p.id===state.selected.id)||state.active:state.active;if(state.active)syncModeToPreset(state.active.id);renderPresets();renderActive()}catch(e){$('#preset-list').innerHTML=`<div class="empty-state">Nie udało się wczytać presetów: ${esc(e.message)}</div>`;$('#rules-list').innerHTML='<div class="empty-state">Sprawdź połączenie z aplikacją i odśwież widok.</div>'}}
async function selectPreset(id){const p=state.presets.find(x=>x.id===id);if(!p)return;state.selected=p;if(state.active?.id!==p.id){try{await post(`/api/presets/${encodeURIComponent(id)}/activate`);state.active=p;syncModeToPreset(p.id);renderActive();toast(`Aktywowano preset: ${p.name}`)}catch(e){toast(e.message)}}renderPresets()}
async function saveSelected(){if(!state.selected)return;$('#save-state').textContent='● Zapisywanie…';try{state.selected=await api(`/api/presets/${encodeURIComponent(state.selected.id)}`,{method:'PUT',body:JSON.stringify(state.selected)});state.presets=state.presets.map(p=>p.id===state.selected.id?state.selected:p);if(state.active?.id===state.selected.id)state.active=state.selected;renderPresets();renderActive();$('#save-state').textContent='● Zapisano wszystkie zmiany'}catch(e){$('#save-state').textContent='● Nie udało się zapisać';toast(e.message)}}
function refreshTestActionOptions(){const prefix=$('#parkour-game-mode').value==='dropper'?'dropper_':'parkour_';const choices=actionCatalog.filter(x=>x.id.startsWith(prefix));const select=$('#parkour-test-action'),old=select.value;select.innerHTML=choices.map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');if(choices.some(x=>x.id===old))select.value=old}
function refreshRuleActionOptions(){const prefix=state.selected?.id==='minecraft-dropper'?'dropper_':'parkour_';const choices=actionCatalog.filter(x=>x.id.startsWith(prefix)),select=$('#rule-action'),old=select.value;select.innerHTML=choices.map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');if(choices.some(x=>x.id===old))select.value=old;else if(choices.length)select.value=choices[0].id}
function updateMinecraftModeUI(){const dropper=$('#parkour-game-mode').value==='dropper';$('#minecraft-mode-title').textContent=dropper?'Minecraft · Dropper Arena':'Minecraft · Parkour 100 Levels';$('#minecraft-mode-subtitle').textContent=dropper?'GiftStream wygeneruje lokalną arenę Droppera z pięcioma szybami i wodnymi lądowiskami.':'GiftStream pobierze oficjalny serwer i uruchomi dołączoną mapę 100 Levels lokalnie.';$('#parkour-enabled-label').textContent=dropper?'Wysyłaj akcje presetu Dropper do lokalnej gry':'Wysyłaj akcje presetu Parkour do lokalnej gry';refreshTestActionOptions()}
function fillActionOptions(){api('/api/actions').then(a=>{actionCatalog=a;refreshRuleActionOptions();refreshTestActionOptions();updateActionHelp()})}
function updateActionHelp(){const descriptions={parkour_push:'Delikatnie odsuwa gracza o 3 bloki; dodaje krótki efekt spadania.',parkour_level_forward:'Przenosi gracza na kolejny obszar mapy, maksymalnie do poziomu 100.',parkour_level_back:'Przenosi gracza na poprzedni obszar mapy, nie niżej niż poziom 1.',parkour_jail:'Przenosi gracza do więzienia na 20 sekund.',parkour_reset:'Rozpoczyna 60-sekundowe odliczanie resetu mapy.',parkour_antireset:'Anuluje rozpoczęte odliczanie resetu.',parkour_speed:'Daje efekt szybkości na 8 sekund.',parkour_slow:'Spowalnia gracza na 7 sekund.',parkour_blind:'Nakłada efekt ciemności na 4 sekundy.',parkour_jump:'Wysoki skok z powolnym opadaniem dla bezpieczniejszego lądowania.',parkour_shield:'Daje odporność na obrażenia na 6 sekund.',parkour_cleanse:'Usuwa wybrane negatywne efekty bez kasowania wszystkich wzmocnień.',dropper_push:'Delikatnie przesuwa gracza do tyłu w szybie.',dropper_level_forward:'Przenosi do następnego z pięciu szybów Droppera.',dropper_level_back:'Przenosi do poprzedniego szybu Droppera.',dropper_reset:'Teleportuje na górę pierwszego szybu.',dropper_speed:'Daje efekt szybkości na 8 sekund.',dropper_slow:'Spowalnia gracza na 7 sekund.',dropper_blind:'Nakłada efekt ciemności na 4 sekundy.',dropper_jump:'Wysoki skok z powolnym opadaniem.',dropper_shield:'Daje odporność na obrażenia na 6 sekund.',dropper_cleanse:'Usuwa wybrane negatywne efekty.'};$('#action-help').textContent=descriptions[$('#rule-action').value]||'Akcja zostanie uruchomiona w lokalnym trybie Minecraft.'}
function renderRuleSoundChoice(ruleSound=''){const select=$('#rule-sound-choice');select.innerHTML='<option value="">Bez osobnego dźwięku</option>';const globalUrl=state.liveConfig.sound_url||'';if(globalUrl){const option=document.createElement('option');option.value='studio';option.textContent=`Dźwięk ze Studio: ${state.liveConfig.sound_label||'wybrany dźwięk'}`;select.append(option)}state.ruleSoundChoice=ruleSound||null;if(ruleSound&&ruleSound!==globalUrl){const option=document.createElement('option');option.value='existing';option.textContent='Zachowaj dźwięk zapisany w tej regule';select.append(option);select.value='existing'}else select.value=ruleSound&&globalUrl?'studio':'';$('#rule-sound-test').disabled=!(select.value==='studio'?globalUrl:select.value==='existing'?state.ruleSoundChoice:'')}
function giftPickerKey(g){return g.id!=null?`id:${g.id}`:`name:${String(g.name||'').toLowerCase()}`}
function renderRuleGiftPicker(query='') {const select=$('#rule-gift'),box=$('#rule-gift-options'),needle=String(query||'').trim().toLocaleLowerCase('pl-PL');if(!select||!box)return;const options=state.gifts||[];select.innerHTML=options.map(g=>`<option value="${esc(giftPickerKey(g))}">${esc(g.label_pl||giftPL[g.name]||g.name)}</option>`).join('');const selected=state.ruleGiftChoice||options[0]||null;if(selected){select.value=giftPickerKey(selected);$('#rule-gift-selected').innerHTML=`${giftArt(selected.name,selected.id,'rule-picker-art')}<span><b>${esc(selected.label_pl||giftPL[selected.name]||selected.name)}</b><small>${esc(coinText(selected.coins,selected.coins_estimated))}</small></span><i>WYBRANO</i>`}else{$('#rule-gift-selected').innerHTML='<span>◇</span><small>Brak prezentów w katalogu — odśwież bibliotekę</small>'}const matches=options.filter(g=>!needle||`${g.name||''} ${g.label_pl||''} ${g.id||''}`.toLocaleLowerCase('pl-PL').includes(needle));const shown=matches.slice(0,needle?30:12);box.innerHTML=shown.map(g=>`<button class="rule-gift-option ${selected&&giftPickerKey(selected)===giftPickerKey(g)?'selected':''}" type="button" role="option" aria-selected="${!!selected&&giftPickerKey(selected)===giftPickerKey(g)}" data-rule-gift="${esc(giftPickerKey(g))}">${giftArt(g.name,g.id,'rule-option-art')}<span><b>${esc(g.label_pl||giftPL[g.name]||g.name)}</b><small>${esc(g.name)} · ${esc(coinText(g.coins,g.coins_estimated))}</small></span></button>`).join('')||'<div class="rule-gift-empty">Nie znaleziono giftów. Spróbuj angielskiej nazwy albo odśwież katalog.</div>';if(matches.length>shown.length)box.insertAdjacentHTML('beforeend',`<div class="rule-gift-empty">Pokazuję ${shown.length} z ${matches.length} wyników — doprecyzuj wyszukiwanie.</div>`);box.querySelectorAll('[data-rule-gift]').forEach(button=>button.onclick=()=>{state.ruleGiftChoice=options.find(g=>giftPickerKey(g)===button.dataset.ruleGift)||null;select.value=state.ruleGiftChoice?giftPickerKey(state.ruleGiftChoice):'';renderRuleGiftPicker('');$('#rule-gift-search').value='';$('#rule-gift-search').focus()});bindGiftArt(box);bindGiftArt($('#rule-gift-selected'))}
function fillGifts(){return api('/api/gifts?sort=popular').then(a=>{state.gifts=a;state.displayGifts=a;renderRuleGiftPicker($('#rule-gift-search')?.value||'');renderRules();if($('#view-gifts').classList.contains('active'))renderGiftLibrary();return a})}
function warmGiftArtwork(){fillGifts().then(gifts=>{if(gifts.filter(g=>g.image_url).length<80&&!catalogRefreshAttempted){catalogRefreshAttempted=true;post('/api/gifts/refresh').then(()=>fillGifts()).catch(()=>{})}}).catch(()=>{})}
function openRule(rule=null){if(!state.selected)return;const form=$('#rule-form');form.reset();$('#rule-id').value=rule?.id||'';$('#rule-modal-title').textContent=rule?'Edytuj regułę':'Dodaj regułę';$('#rule-name').value=rule?.name||'';$('#rule-trigger').value=rule?.trigger?.type||'gift';const catalogGift=(rule?.trigger?.gift_id!=null?state.gifts.find(g=>String(g.id)===String(rule.trigger.gift_id)):null)||state.gifts.find(g=>String(g.name).toLowerCase()===String(rule?.trigger?.gift_name||'Rose').toLowerCase());state.ruleGiftChoice=catalogGift||(rule?.trigger?.gift_name?{id:rule.trigger.gift_id,name:rule.trigger.gift_name,label_pl:giftPL[rule.trigger.gift_name]||rule.trigger.gift_name,coins:0,coins_estimated:true}:state.gifts[0]||null);$('#rule-gift-search').value='';renderRuleGiftPicker('');$('#rule-min-coins').value=rule?.trigger?.min_coins??'';$('#rule-max-coins').value=rule?.trigger?.max_coins??'';$('#rule-keyword').value=rule?.trigger?.keyword||'';$('#rule-threshold').value=rule?.trigger?.like_threshold||100;$('#rule-action').value=rule?.action?.type||'parkour_push';$('#rule-cooldown').value=rule?.cooldown_sec||0;$('#rule-params').value=JSON.stringify(rule?.action?.params||{count:1});$('#rule-alert').value=cleanEmoji(rule?.alert_text||'');renderRuleSoundChoice(rule?.sound||'');$('#rule-interrupt').checked=!!rule?.interrupt;toggleRuleFields();$('#rule-dialog').showModal()}
function toggleRuleFields(){const t=$('#rule-trigger').value;$('#gift-field').classList.toggle('hidden',t!=='gift');$('#keyword-field').classList.toggle('hidden',t!=='comment');$('#threshold-field').classList.toggle('hidden',t!=='like')}
function saveRule(){const p=state.selected;if(!p)return;let params;try{params=JSON.parse($('#rule-params').value||'{}')}catch{toast('Parametry akcji muszą być poprawnym JSON-em');return}const type=$('#rule-trigger').value,trigger={type};if(type==='gift'){const chosenGift=state.ruleGiftChoice;if(!chosenGift){toast('Wybierz prezent z katalogu, aby zapisać regułę');return}trigger.gift_name=chosenGift.name;if(chosenGift.id!=null)trigger.gift_id=Number(chosenGift.id);const minCoins=$('#rule-min-coins').value.trim(),maxCoins=$('#rule-max-coins').value.trim();if(minCoins!=='')trigger.min_coins=Number(minCoins);if(maxCoins!=='')trigger.max_coins=Number(maxCoins);if(trigger.min_coins!=null&&trigger.max_coins!=null&&trigger.max_coins<trigger.min_coins){toast('Maksymalna cena monet nie może być niższa od minimum');return}}if(type==='comment')trigger.keyword=$('#rule-keyword').value;if(type==='like')trigger.like_threshold=Number($('#rule-threshold').value)||100;const act=$('#rule-action').value;const oldId=$('#rule-id').value;const existing=p.rules.find(r=>r.id===oldId),soundMode=$('#rule-sound-choice').value,sound=soundMode==='studio'?state.liveConfig.sound_url:soundMode==='existing'?state.ruleSoundChoice:null;if(soundMode==='studio'&&!sound){toast('Najpierw wybierz dźwięk w Studio dźwięków');return}const rule={id:oldId||`rule_${Math.random().toString(36).slice(2,9)}`,name:$('#rule-name').value.trim()||`${trigger.gift_name||trigger.keyword||type} → ${act.replaceAll('_',' ')}`,enabled:existing?.enabled??true,trigger,action:{type:act,params},cooldown_sec:Number($('#rule-cooldown').value)||0,interrupt:$('#rule-interrupt').checked,alert_text:$('#rule-alert').value,sound:sound||null};if(existing)p.rules=p.rules.map(r=>r.id===oldId?rule:r);else p.rules.push(rule);$('#rule-dialog').close();saveSelected()}
async function refreshSnapshot(){try{const s=await api('/api/snapshot');state.events=s.recent_events||[];state.actions=s.recent_actions||[];state.totalDiamonds=Number(s.total_diamonds)||0;state.totalGifts=Number(s.total_gifts)||0;state.donors=s.top_donors||[];renderFeed();renderEarnings();renderDonors(state.donors);$('#metric-viewers').textContent=s.viewer_count?Number(s.viewer_count).toLocaleString('pl-PL'):'—';$('#metric-likes').textContent=Number(s.total_likes||0).toLocaleString('pl-PL');$('#metric-events').textContent=s.stats?.events||state.events.length;$('#metric-actions').textContent=s.stats?.actions||state.actions.length;setConnection(s.connector||{});if(s.preset&&s.preset.id!==state.active?.id){state.active=s.preset;renderActive()}}catch{}}
function setConnection(c){state.connected=!!c.connected;state.connectionState=c.state||(state.connected?'connected':'disconnected');state.activeMode=c.mode||'tiktok';state.activeUsername=c.username||'';if(!state.connectionInitialized){state.selectedMode=state.activeMode==='managed'?'managed':'tiktok';$('#mode-select').value=state.selectedMode;$('#username-input').value=c.username||'';state.connectionInitialized=true}const led=$('#side-led'),pending=['connecting','reconnecting','stopping','offline'].includes(state.connectionState),active=state.connected||pending;led.classList.toggle('on',state.connected);const modeName=c.mode==='managed'?'Zewnętrzne API':'TikTok LIVE',stateName={connecting:'ŁĄCZENIE',reconnecting:'PONAWIAM',offline:'OFFLINE · SPRAWDZAM',stopping:'ROZŁĄCZANIE',error:'BŁĄD',disconnected:'ROZŁĄCZONO'}[state.connectionState];$('#side-status').textContent=state.connectionState==='connected'?'Połączono':state.connectionState==='connecting'?'Łączenie…':state.connectionState==='reconnecting'?'Ponawiam połączenie…':state.connectionState==='offline'?'Kanał offline · sprawdzam ponownie':state.connectionState==='error'?'Błąd połączenia':'Rozłączono';$('#side-username').textContent=active?(c.username?`@${c.username}`:'Kanał LIVE'):(c.username?`@${c.username}`:'TikTok LIVE gotowy');$('#connection-pill').textContent=state.connectionState==='connected'?modeName.toLocaleUpperCase('pl-PL'):stateName||modeName.toLocaleUpperCase('pl-PL');$('#connection-pill').className=`pill ${state.connectionState==='connected'?'pill-live':pending?'pill-warning':'pill-muted'}`;$('#connect-description').textContent=c.last_error?`${c.last_error}${c.retry_in?` · ponowna próba za ${c.retry_in} s`:''}`:state.connectionState==='connecting'?`Łączę z ${c.username?`@${c.username}`:'kanałem'}… Logi diagnostyczne poniżej.`:state.connectionState==='reconnecting'?`Połączenie przerwane; automatyczna próba nr ${c.retry_attempt||1}${c.retry_in?` za ${c.retry_in} s`:''}. Nie klikaj ponownie — szczegóły są w logach.`:state.connected?`Odbieram zdarzenia LIVE${c.username?` z kanału @${c.username}`:''}.`:'Wybierz TikTok LIVE i połącz kanał, aby zacząć zbierać prawdziwe statystyki.';$('#mode-select').value=state.selectedMode||'tiktok';syncConnectionInputs();updateConnectButton()}
async function loadLiveTools(){try{const c=await api('/api/config');state.liveConfig={...state.liveConfig,...c,tts_enabled:!!c.tts_enabled,tts_voice:c.tts_voice||'pl-PL',sound_alerts:!!c.sound_alerts,sound_volume:Number(c.sound_volume??.55),sound_url:c.sound_url||'',sound_label:c.sound_label||'',overlay_template:['grid','list','minimal','streamer','ticker','spotlight','arena'].includes(c.overlay_template)?c.overlay_template:'grid'};const overlayChoice=$(`input[name="template"][value="${state.liveConfig.overlay_template}"]`);if(overlayChoice){overlayChoice.checked=true;$$('.template-option').forEach(x=>x.classList.toggle('selected',x.contains(overlayChoice)))}$('#overlay-theme').value=['mint','violet','amber','ocean'].includes(c.overlay_theme)?c.overlay_theme:'mint';$('#overlay-accent').value=/^#[0-9a-f]{6}$/i.test(c.overlay_accent||'')?c.overlay_accent:'#8cf0bc';$('#overlay-scale').value=Math.round((Number(c.overlay_scale)||1)*100);$('#overlay-title').value=c.overlay_title||'';const overlayFields=new Set(String(c.overlay_fields||'earnings,gifts,actions,viewers,likes,leaderboard').split(','));$$('[data-overlay-field]').forEach(x=>x.checked=overlayFields.has(x.dataset.overlayField));$('#overlay-opacity').value=Math.round((Number(c.overlay_opacity)||.72)*100);$('#overlay-density').value=['compact','balanced','bold'].includes(c.overlay_density)?c.overlay_density:'balanced';$('#overlay-canvas').value=['landscape','portrait'].includes(c.overlay_canvas)?c.overlay_canvas:'landscape';state.liveConfig.overlay_positions_landscape=c.overlay_positions_landscape||state.liveConfig.overlay_positions_landscape;state.liveConfig.overlay_positions_portrait=c.overlay_positions_portrait||state.liveConfig.overlay_positions_portrait;updateOverlayPreview();$('#tts-enabled').checked=state.liveConfig.tts_enabled;$('#tts-voice').value=state.liveConfig.tts_voice;$('#sound-alerts').checked=state.liveConfig.sound_alerts;$('#sound-volume').value=Math.round(state.liveConfig.sound_volume*100);$('#sound-volume-label').textContent=`${Math.round(state.liveConfig.sound_volume*100)}%`;$('#sound-url').value=state.liveConfig.sound_url;renderSelectedSound()}catch{}}
async function saveLiveTools(patch){state.liveConfig={...state.liveConfig,...patch};try{const saved=await api('/api/config',{method:'PUT',body:JSON.stringify(patch)});state.liveConfig={...state.liveConfig,...saved};toast('Zapisano ustawienia alertów')}catch(e){toast(e.message);loadLiveTools()}}
async function saveSoundUrl(){const value=$('#sound-url').value.trim(),old=state.liveConfig.sound_url;try{const saved=await api('/api/config',{method:'PUT',body:JSON.stringify({sound_url:value,sound_label:value?'Własny link audio':''})});state.liveConfig.sound_url=saved.sound_url||'';state.liveConfig.sound_label=saved.sound_label||'';$('#sound-url').value=state.liveConfig.sound_url;renderSelectedSound();toast(state.liveConfig.sound_url?'Zapisano własny dźwięk':'Przywrócono wbudowany sygnał')}catch(e){toast(e.message)}}
async function uploadSound(){const input=$('#sound-file'),file=input.files?.[0],button=$('#upload-sound'),status=$('#sound-upload-status');if(!file){status.textContent='Najpierw wybierz plik dźwiękowy.';return}if(file.size>10*1024*1024){status.textContent='Plik przekracza limit 10 MB.';return}button.disabled=true;status.textContent='Wgrywam i zapisuję plik…';const old=state.liveConfig.sound_url;try{const response=await fetch(`/api/sounds/upload?filename=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file,cache:'no-store'});const asset=await response.json();if(!response.ok)throw new Error(asset.detail||'Nie udało się zapisać pliku');const saved=await api('/api/config',{method:'PUT',body:JSON.stringify({sound_url:asset.url,sound_label:file.name.slice(0,100),sound_alerts:true})});state.liveConfig={...state.liveConfig,...saved};$('#sound-url').value=state.liveConfig.sound_url;$('#sound-alerts').checked=true;renderSelectedSound();status.textContent=`Gotowe: ${file.name} · ${(file.size/1024).toFixed(0)} KB`;toast('Wgrano i wybrano własny dźwięk')}catch(e){status.textContent=e.message;toast(e.message)}finally{button.disabled=false;input.value=''}}
