function renderSelectedSound(){const label=state.liveConfig.sound_label||'';let host='';try{host=new URL(state.liveConfig.sound_url).hostname.toLowerCase()}catch{}const url=state.liveConfig.sound_url||'';$('#sound-selected-title').textContent=label||'Sygnał GiftStream';$('#sound-selected-subtitle').textContent=url?url.startsWith('/api/sounds/uploads/')?'Plik zapisany lokalnie':(['www.myinstants.com','myinstants.com'].includes(host)?'MyInstants · gotowy do testu':'Zapisany link audio'):'Wbudowany dźwięk GiftStream';$('#sound-ready-pill').textContent=url?'WYBRANY':'GOTOWY';$('#clear-sound').disabled=!url}
async function selectMyInstant(sound){const old=state.liveConfig.sound_url;try{const saved=await api('/api/config',{method:'PUT',body:JSON.stringify({sound_url:sound.url,sound_label:sound.name,sound_alerts:true})});state.liveConfig={...state.liveConfig,...saved};$('#sound-url').value=state.liveConfig.sound_url;$('#sound-alerts').checked=true;renderSelectedSound();toast(`Ustawiono alert: ${sound.name}`)}catch(e){toast(e.message)}}
function playAudioClip(url,reportError=false){try{const audio=new Audio(url),volume=Number(state.liveConfig.sound_volume);audio.volume=Math.max(0,Math.min(1,Number.isFinite(volume)?volume:.55));audio.preload='auto';let stopTimer;audio.addEventListener('playing',()=>{stopTimer=setTimeout(()=>audio.pause(),MAX_SOUND_CLIP_SECONDS*1000)},{once:true});audio.addEventListener('ended',()=>clearTimeout(stopTimer),{once:true});audio.play().catch(()=>{if(reportError)toast('Nie udało się odtworzyć tego pliku. Spróbuj innego wyniku.')});return audio}catch{if(reportError)toast('Nie udało się odtworzyć tego pliku. Spróbuj innego wyniku.');return null}}function previewSound(url){return playAudioClip(url,true)}
async function clearActivity(){try{const result=await post('/api/stats/clear-activity');await refreshSnapshot();toast(result.message)}catch(e){toast(e.message)}}
async function resetStats(){if(!window.confirm('Wyzerować liczniki, ranking widzów, aktywność i statystyki akcji dla bieżącej sesji?'))return;const button=$('#reset-stats');button.disabled=true;try{const result=await post('/api/stats/reset');await refreshSnapshot();toast(result.message)}catch(e){toast(e.message)}finally{button.disabled=false}}
async function searchMyInstants(){const query=$('#myinstants-query').value.trim(),box=$('#myinstants-results'),button=$('#myinstants-search-button');if(!query){box.innerHTML='<div class="sound-empty"><strong>Wpisz nazwę dźwięku, aby rozpocząć wyszukiwanie.</strong></div>';$('#myinstants-query').focus();return}button.disabled=true;button.textContent='Szukam…';box.innerHTML='<div class="sound-empty"><span class="sound-loading"></span><strong>Łączę z MyInstants…</strong><small>Wyniki pojawią się tutaj.</small></div>';try{const result=await api(`/api/sounds/myinstants?q=${encodeURIComponent(query)}`);box.replaceChildren();if(!result.results?.length){box.innerHTML='<div class="sound-empty"><span>⌕</span><strong>Nie znaleziono pasujących plików audio</strong><small>Spróbuj krótszego hasła, np. „bruh”, „victory” albo „applause”.</small></div>';return}for(const sound of result.results){const row=document.createElement('article');row.className='myinstants-result';const number=document.createElement('span');number.className='sound-result-mark';number.textContent='♫';const text=document.createElement('div');text.className='sound-result-copy';const name=document.createElement('strong');name.textContent=sound.name;const host=document.createElement('small');host.textContent='MYINSTANTS · MP3';text.append(name,host);const preview=document.createElement('button');preview.type='button';preview.className='button button-secondary small';preview.textContent='▶ Odsłuchaj';preview.setAttribute('aria-label',`Odsłuchaj ${sound.name}`);preview.onclick=()=>previewSound(sound.url);const add=document.createElement('button');add.type='button';add.className='button button-primary small';add.textContent=state.liveConfig.sound_url===sound.url?'Wybrany ✓':'Ustaw alert';add.disabled=state.liveConfig.sound_url===sound.url;add.onclick=()=>selectMyInstant(sound);row.append(number,text,preview,add);box.append(row)}}catch(e){box.innerHTML=`<div class="sound-error"><strong>Wyszukiwarka MyInstants chwilowo nie odpowiada</strong><small>${esc(e.message)}. Możesz też wkleić publiczny link HTTPS po prawej.</small></div>`}finally{button.disabled=false;button.innerHTML='Szukaj dźwięków <span>⌕</span>'}}
function speakText(text,voice=state.liveConfig.tts_voice){if(!('speechSynthesis'in window)||!text)return;try{speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=voice;utterance.rate=1;utterance.pitch=1;const match=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(voice.toLowerCase()));if(match)utterance.voice=match;speechSynthesis.speak(utterance)}catch{}}
function speakLiveEvent(ev){if(!state.liveConfig.tts_enabled||!ev||Date.now()-state.lastSpeechAt<2200)return;if(!['gift','follow','subscribe'].includes(ev.type))return;state.lastSpeechAt=Date.now();const who=ev.nickname||ev.user||'Widz';const gift=giftPL[ev.gift_name]||ev.gift_name||'prezent';speakText(ev.type==='gift'?`${who} wysłał prezent ${gift}${ev.repeat_count>1?` razy ${ev.repeat_count}`:''}`:ev.type==='follow'?`${who} zaczął obserwować kanał`:`${who} zasubskrybował kanał`)}
function playSoundUrl(url){playAudioClip(url,false)}
function playSoundAlert(force=false){if(!force&&!state.liveConfig.sound_alerts)return;try{if(state.liveConfig.sound_url){playSoundUrl(state.liveConfig.sound_url);return}const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return;const context=state.audioContext||(state.audioContext=new AudioContextClass());if(context.state==='suspended')context.resume();const osc=context.createOscillator(),gain=context.createGain(),now=context.currentTime;osc.type='sine';osc.frequency.setValueAtTime(880,now);osc.frequency.exponentialRampToValueAtTime(1174,now+.12);gain.gain.setValueAtTime(Math.max(.001,state.liveConfig.sound_volume*.12),now);gain.gain.exponentialRampToValueAtTime(.001,now+.28);osc.connect(gain);gain.connect(context.destination);osc.start(now);osc.stop(now+.3)}catch{}}
function announceEvent(ev){if(['gift','follow','subscribe'].includes(ev?.type)&&Date.now()-state.lastSoundAt>700){state.lastSoundAt=Date.now();playSoundAlert()}speakLiveEvent(ev)}
function connectWS(){const proto=location.protocol==='https:'?'wss':'ws';const ws=new WebSocket(`${proto}://${location.host}/ws/feed`);state.ws=ws;ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.kind==='event'){state.events.push(m.data);state.events=state.events.slice(-200);announceEvent(m.data);if(m.data.type==='like')$('#metric-likes').textContent=(Number($('#metric-likes').textContent.replaceAll(',',''))+(m.data.like_count||1)).toLocaleString('pl-PL');$('#metric-events').textContent=Number($('#metric-events').textContent.replaceAll(',',''))+1;renderFeed()}else if(m.kind==='action'){state.actions.push(m.data);state.actions=state.actions.slice(-200);if(m.data.params?.sound&&!(state.liveConfig.sound_alerts&&m.data.params.sound===state.liveConfig.sound_url&&['gift','follow','subscribe'].includes(m.data.triggered_by?.type)&&Date.now()-state.lastSoundAt<1200))playSoundUrl(m.data.params.sound);$('#metric-actions').textContent=Number($('#metric-actions').textContent.replaceAll(',',''))+1;renderFeed()}else if(m.kind==='action_status'){const action=state.actions.find(a=>a.action_id===m.data.action_id);if(action){action.execution_status=m.data.execution_status;action.execution_message=m.data.execution_message;action.execution_updated_at=m.data.execution_updated_at;renderFeed()}}else if(m.kind==='snapshot'){if(m.data.recent_events){state.events=m.data.recent_events;state.actions=m.data.recent_actions||[];state.totalDiamonds=Number(m.data.total_diamonds)||0;state.totalGifts=Number(m.data.total_gifts)||0;state.donors=m.data.top_donors||[];renderFeed();renderEarnings();renderDonors(state.donors)}}};ws.onclose=()=>setTimeout(connectWS,1800);ws.onerror=()=>ws.close()}
