async function saveOverlayOptions(){const fields=$$('[data-overlay-field]:checked').map(x=>x.dataset.overlayField).join(','),patch={overlay_template:$('input[name="template"]:checked')?.value||'grid',overlay_theme:$('#overlay-theme').value,overlay_accent:$('#overlay-accent').value,overlay_scale:(Number($('#overlay-scale').value)||100)/100,overlay_opacity:(Number($('#overlay-opacity').value)||72)/100,overlay_density:$('#overlay-density').value||'balanced',overlay_canvas:$('#overlay-canvas').value||'landscape',overlay_positions_landscape:state.liveConfig.overlay_positions_landscape,overlay_positions_portrait:state.liveConfig.overlay_positions_portrait,overlay_title:$('#overlay-title').value.trim(),overlay_fields:fields};state.liveConfig={...state.liveConfig,...patch};updateOverlayPreview();try{const saved=await api('/api/config',{method:'PUT',body:JSON.stringify(patch)});state.liveConfig={...state.liveConfig,...saved}}catch(e){toast(`Nie udało się zapisać nakładki: ${e.message}`)}}
