function updateConnectButton(){const button=$('#connect-button'),mode=state.selectedMode||$('#mode-select').value,active=state.connected||['connecting','reconnecting','stopping','offline'].includes(state.connectionState),requested=$('#username-input').value.trim().replace(/^@/,'').toLowerCase(),current=(state.activeUsername||'').replace(/^@/,'').toLowerCase(),sameChannel=mode!=='tiktok'||requested===current,sameConnection=active&&mode===state.activeMode&&sameChannel;button.innerHTML=sameConnection?(state.connectionState==='offline'?'Wstrzymaj sprawdzanie <span>×</span>':state.connectionState==='connecting'||state.connectionState==='reconnecting'?'Anuluj łączenie <span>×</span>':'Rozłącz <span>×</span>'):active?`Przełącz na ${mode==='tiktok'?(requested?`@${esc(requested)}`:'TikTok LIVE'):'zewnętrzne API'} <span>↗</span>`:'Połącz <span>↗</span>';button.title=sameConnection?'Zatrzymaj bieżącą sesję lub ponawianie połączenia':'Połącz w wybranym trybie';button.setAttribute('aria-label',button.title)}
