async function connectAction(){const button=$('#connect-button'),mode=state.selectedMode||$('#mode-select').value,active=state.connected||['connecting','reconnecting','stopping','offline'].includes(state.connectionState),requested=$('#username-input').value.trim().replace(/^@/,'').toLowerCase(),current=(state.activeUsername||'').replace(/^@/,'').toLowerCase(),sameChannel=mode!=='tiktok'||requested===current;button.disabled=true;try{if(active&&mode===state.activeMode&&sameChannel){await post('/api/disconnect');await refreshSnapshot();await loadDiagnostics();return}const username=$('#username-input').value.trim();if(mode==='tiktok'&&!username){$('#username-input').focus();setConnectError('Wpisz nazwę kanału TikTok LIVE.');return}$('#connect-description').textContent='Uruchamiam połączenie… Szczegóły i błędy pojawią się w logach poniżej.';const r=await post('/api/connect',{mode,username});if(!r.ok){setConnectError(r.message||'Połączenie nie zostało uruchomione.');await loadDiagnostics();await refreshSnapshot();return}state.selectedMode=mode;await refreshSnapshot();await loadDiagnostics()}catch(e){setConnectError(e.message);await loadDiagnostics()}finally{button.disabled=false;updateConnectButton()}}
