function renderDiagnostics(){const text=state.logs.length?state.logs.join('\n'):'Brak logów. Błędy połączenia, Minecraft, akcji, API i interfejsu pojawią się tutaj.';$$('.diagnostics-output').forEach(box=>{box.textContent=text;box.scrollTop=box.scrollHeight})}
