async function loadGiftLibrary(q=''){state.giftPage=0;const sequence=++giftLoadSequence,params=new URLSearchParams({sort:state.giftSort});if(q)params.set('q',q);try{state.displayGifts=await api(`/api/gifts?${params}`);if(sequence!==giftLoadSequence)return;renderGiftLibrary()}catch(e){if(sequence===giftLoadSequence)$('#gift-grid').innerHTML=`<div class="empty-state">Nie udało się wczytać biblioteki: ${esc(e.message)}</div>`;return}if(!q&&!catalogRefreshAttempted&&state.gifts.filter(g=>g.image_url).length<80){catalogRefreshAttempted=true;$('#gift-count').textContent='Pobieram katalog TikTok…';try{await post('/api/gifts/refresh');await fillGifts();if(sequence!==giftLoadSequence)return;state.displayGifts=await api(`/api/gifts?${params}`);renderGiftLibrary()}catch{if(sequence===giftLoadSequence)$('#gift-count').textContent='Katalog offline · zachowano zapisany katalog'}}}
