async function loadParkourVersions(){const select=$('#parkour-version');try{const data=await api('/api/minecraft/versions');const previous=select.value;select.innerHTML=`<option value="latest">Najnowsza stabilna · ${esc(data.latest)}</option>`+data.versions.map(v=>`<option value="${esc(v.id)}">Minecraft ${esc(v.id)}${v.id===data.map_version?' · wersja mapy':''}</option>`).join('');$('#parkour-map-version').textContent=`mapa ${data.map_version}`;select.value=previous&&[...select.options].some(o=>o.value===previous)?previous:'latest';if(!parkourVersionInitialized)await loadParkourStatus()}catch(e){select.innerHTML='<option value="latest">Najnowsza stabilna</option>';$('#parkour-status').textContent=`Nie udało się pobrać listy wersji: ${e.message}`}}
